import re, collections
cut_texts = ' '.join(r['text'] for r in cut)
fin_texts = ' '.join(r['text'] for r in fin)
def line_openers(t):
    return collections.Counter(m.group(1) for m in re.finditer(r'\n\s*([A-Za-z]+)', t))
co = line_openers(cut_texts); fo = line_openers(fin_texts)
tot_c = sum(co.values()); tot_f = sum(fo.values())
words = set(co)|set(fo)
diffs = sorted(((co[w]/tot_c - fo[w]/tot_f, w, co[w], fo[w]) for w in words), reverse=True)
for d,w,a,b in diffs[:25]: print(f'{d*1000:.2f} per1k  {w}  cut={a} fin={b}')

